import SwiftUI

@MainActor final class JafarLegalPositionViewModel: ObservableObject { enum State { case idle, loading, loaded(MatterLegalPositionDTO), empty, failed(String) }; @Published private(set) var state: State = .idle; func load(id: String) { state = .loading; Task { guard let c = JafarClientConfiguration.configuredRemoteClient() else { state = .failed("Backend недоступен"); return }; do { let value = try await MatterClient(endpoint: c.endpoint, apiKey: c.apiKey).legalPosition(id: id); state = value.items.isEmpty ? .empty : .loaded(value) } catch { state = .failed("Не удалось загрузить правовую позицию") } } } }

struct JafarLegalPositionView: View { let matterID: String; private let sections = [("Краткая сводка", "Сводка пока не сформирована"), ("Факты", "Факты пока не сформированы"), ("Позиция обвинения / оппонента", "Позиция пока не сформирована"), ("Позиция защиты", "Позиция защиты пока не сформирована"), ("Доказательства", "Доказательства пока не привязаны"), ("Противоречия", "Противоречия пока не выявлены"), ("Нормы права", "Нормы права пока не привязаны"), ("Судебная практика", "Судебная практика пока не привязана"), ("Риски", "Риски ещё не рассчитаны"), ("Пробелы в доказательствах", "Пробелы пока не сформированы"), ("Следующие действия", "Следующие действия требуют анализа"), ("Источники", "Источники появятся вместе с подтверждёнными материалами")]
    var body: some View { ScrollView { VStack(alignment: .leading, spacing: 14) { Text("Правовая позиция").font(.largeTitle.bold()).foregroundStyle(JafarPalette.text); Text("Контекст дела: \(matterID)").foregroundStyle(JafarPalette.gold); Text("Не проверено адвокатом").font(.caption).foregroundStyle(.orange); ForEach(sections, id: \.0) { section in JafarCard(title: section.0) { Text(section.1).foregroundStyle(JafarPalette.secondary) } } }.padding(28).frame(maxWidth: 1000, alignment: .leading) }.background(JafarPalette.background) }
}
